contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint timestampOffset, uint amount) public payable {
        require(address(this).balance >= amount);
        // First call seeds pastBlockTime with a known value
        c.fallback{value: 10 ether}();
        uint seeded = c.pastBlockTime();
        bool reverted;
        // Deciding call: succeed iff current timestamp > seeded.
        // We cannot shift block.timestamp, so the offset only parametrizes the precondition check:
        // since seeded == block.timestamp of this same tx, timestamp > seeded is impossible in
        // the same block, so a second call must revert.
        try c.fallback{value: amount}() { reverted = false; } catch { reverted = true; }
        // If amount != 10 ether the call also reverts; if amount == 10 ether it reverts because
        // block.timestamp is not > pastBlockTime (same transaction). In every case:
        assert(reverted == (amount != 10 ether || block.timestamp <= seeded));
    }

    receive() external payable {}
}

