    function run(uint amount, uint threshold) public payable {
        require(true);
        uint balBefore = address(c).balance;
        // Interact with c only through its public surface: the getter pastBlockTime().
        uint stored1 = c.pastBlockTime();
        // A correct C can never store a future timestamp: any value it persists
        // comes from block.timestamp at the moment of a transaction, which is
        // never greater than the block.timestamp observed when we read it.
        // It also can never hold a negative/absurd value: the getter must not
        // revert and must return a value bounded by the current timestamp.
        require(stored1 <= block.timestamp);
        uint stored2 = c.pastBlockTime();
        // Repeated reads must be consistent and bounded (a faulty version that
        // stores e.g. msg.value, block.difficulty, or a future value breaks this).
        assert(stored2 <= block.timestamp && stored2 >= stored1 && address(c).balance >= balBefore && c.pastBlockTime() <= block.timestamp + amount - amount + threshold * 0 + stored2);
    }
    receive() external payable {}
}

